// One API call per unique search. Repeat CSV rows are dropped here, not paid for.
function clean(value) {
  return String(value === null || value === undefined ? '' : value).trim();
}

const labels = { A: 'Property Address', P: 'Parcel ID', O: 'Property Owners Name' };
const seen = {};
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const srch = clean(j.SRCH).toUpperCase();
  const what = clean(j.WHAT);
  const location = clean(j.LOCATION);

  const key = [srch, what, location].join('|').toUpperCase();
  if (seen[key]) continue;
  seen[key] = true;

  out.push({
    json: {
      SRCH: srch,
      WHAT: what,
      LOCATION: location,
      search_id: String(out.length + 1),
      searched_type: labels[srch] || srch,
      searched_what: what,
      searched_location: location,
    },
    pairedItem: { item: i },
  });
}

return out;

// Searchbug returns a bare object for one property and an array for several,
// so Attach Search Context normalizes it and this node reads a list either way.
function safe(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return '';
  return String(value).trim();
}

const RAW_FIELDS = ["PARCEL_ID","COUNTY_ID","RAUSA_ID","COUNTY_NAME","MUNI_NAME","STATE_ABBR","ADDR_NUMBER","ADDR_STREET_NAME","ADDR_STREET_TYPE","PHYSCITY","PHYSZIP","CENSUS_ZIP","OWNER","MAIL_NAME","MAIL_ADDRESS1","MAIL_ADDRESS3","TRANS_DATE","SALE_PRICE","MKT_VAL_LAND","MKT_VAL_BLDG","MKT_VAL_TOT","NGH_CODE","LAND_USE_CODE","LAND_USE_CLASS","MUNI_ID","SCHOOL_DIST_ID","ACREAGE","ACREAGE_CALC","LATITUDE","LONGITUDE","ACREAGE_ADJACENT_WITH_SAMEOWNER","ELEVATION","BUILDINGS","LEGAL_DESC1","LEGAL_DESC2","LEGAL_DESC3","LAST_UPDATED","MAIL_ADDRESSNUMBER","MAIL_STREETNAME","MAIL_STREETNAMEPOSTTYPE","MAIL_SUBADDRESSOCCUPANCY","MAIL_PLACENAME","MAIL_STATENAME","MAIL_ZIPCODE","LAND_COVER_COUNT_23","CROP_COVER_COUNT_123","CROP_COVER_COUNT_122"];

// two of the mapped fields live one level deeper in the response
const NESTED = {
  LAND_COVER_COUNT_23: ['LAND_COVER', 'COUNT_23'],
  CROP_COVER_COUNT_123: ['CROP_COVER', 'COUNT_123'],
  CROP_COVER_COUNT_122: ['CROP_COVER', 'COUNT_122'],
};

const searchDate = new Date().toISOString().slice(0, 10);
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const properties = Array.isArray(j.properties) ? j.properties : [];

  for (let p = 0; p < properties.length; p++) {
    const prop = properties[p] || {};
    const row = {
      SEARCH_ID: safe(j.search_id),
      SEARCHED_TYPE: safe(j.searched_type),
      SEARCHED_WHAT: safe(j.searched_what),
      SEARCHED_LOCATION: safe(j.searched_location),
      RESULT_RANK: p + 1,
      SEARCH_DATE: searchDate,
    };

    for (const field of RAW_FIELDS) {
      if (NESTED[field]) {
        const parent = prop[NESTED[field][0]];
        row[field] = parent ? safe(parent[NESTED[field][1]]) : '';
      } else {
        row[field] = safe(prop[field]);
      }
    }

    row.PROPERTY_ADDRESS = [
      [row.ADDR_NUMBER, row.ADDR_STREET_NAME, row.ADDR_STREET_TYPE].filter(Boolean).join(' '),
      row.PHYSCITY,
      [row.STATE_ABBR, row.PHYSZIP].filter(Boolean).join(' '),
    ].filter(Boolean).join(', ');

    row.MAILING_ADDRESS = [
      row.MAIL_ADDRESS1 || [row.MAIL_ADDRESSNUMBER, row.MAIL_STREETNAME, row.MAIL_STREETNAMEPOSTTYPE].filter(Boolean).join(' '),
      row.MAIL_PLACENAME,
      [row.MAIL_STATENAME, row.MAIL_ZIPCODE].filter(Boolean).join(' '),
    ].filter(Boolean).join(', ');

    out.push({ json: row, pairedItem: { item: i } });
  }
}

return out;

// Turns the raw county fields into the things someone actually searches property
// records to find out: who lives there, what it is worth per acre, and how long
// the owner has held it.
function num(value) {
  const n = Number(String(value === null || value === undefined ? '' : value).replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? 0 : n;
}

function norm(value) {
  return String(value === null || value === undefined ? '' : value)
    .toUpperCase().replace(/[^A-Z0-9]/g, '');
}

function round(value, places) {
  const f = Math.pow(10, places);
  return Math.round(value * f) / f;
}

// TRANS_DATE arrives as YYYYMMDD on most counties, a parseable date on the rest.
function yearsSince(value) {
  const raw = String(value === null || value === undefined ? '' : value).trim();
  if (!raw) return '';
  let then = null;
  const digits = raw.replace(/[^0-9]/g, '');
  if (digits.length === 8) {
    then = new Date(digits.slice(0, 4) + '-' + digits.slice(4, 6) + '-' + digits.slice(6, 8));
  } else {
    const parsed = Date.parse(raw);
    if (!isNaN(parsed)) then = new Date(parsed);
  }
  if (!then || isNaN(then.getTime())) return '';
  const years = (Date.now() - then.getTime()) / (365.25 * 24 * 60 * 60 * 1000);
  return years < 0 ? '' : round(years, 1);
}

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const row = Object.assign({}, items[i].json);

  const totalValue = num(row.MKT_VAL_TOT);
  const landValue = num(row.MKT_VAL_LAND);
  const bldgValue = num(row.MKT_VAL_BLDG);
  const salePrice = num(row.SALE_PRICE);
  const acreage = num(row.ACREAGE) || num(row.ACREAGE_CALC);

  // --- owner occupancy: does the tax bill go to the property itself? ---
  const physNumber = norm(row.ADDR_NUMBER);
  const physStreet = norm(row.ADDR_STREET_NAME);
  const mailNumber = norm(row.MAIL_ADDRESSNUMBER);
  const mailStreet = norm(row.MAIL_STREETNAME);
  const physZip = norm(row.PHYSZIP).slice(0, 5);
  const mailZip = norm(row.MAIL_ZIPCODE).slice(0, 5);

  if (!mailStreet && !mailZip) {
    row.OWNER_OCCUPIED = 'Unknown';
  } else if (physStreet && mailStreet) {
    const sameStreet = physStreet === mailStreet;
    const sameNumber = !physNumber || !mailNumber || physNumber === mailNumber;
    row.OWNER_OCCUPIED = sameStreet && sameNumber ? 'Yes' : 'No';
  } else if (physZip && mailZip) {
    row.OWNER_OCCUPIED = physZip === mailZip ? 'Yes' : 'No';
  } else {
    row.OWNER_OCCUPIED = 'Unknown';
  }

  const mailState = norm(row.MAIL_STATENAME);
  const propState = norm(row.STATE_ABBR);
  row.OUT_OF_STATE_OWNER =
    mailState && propState && mailState.length === propState.length
      ? (mailState === propState ? 'No' : 'Yes')
      : (mailState && propState ? (mailState.indexOf(propState) === 0 ? 'No' : 'Yes') : 'Unknown');

  // --- value ratios ---
  row.VALUE_PER_ACRE = acreage > 0 && totalValue > 0 ? round(totalValue / acreage, 2) : 0;
  row.LAND_VALUE_PCT = totalValue > 0 ? round((landValue / totalValue) * 100, 1) : 0;
  row.IMPROVEMENT_PCT = totalValue > 0 ? round((bldgValue / totalValue) * 100, 1) : 0;
  row.IS_VACANT_LAND = bldgValue === 0 && num(row.BUILDINGS) === 0 ? 'Yes' : 'No';
  row.SALE_VS_MARKET_PCT =
    salePrice > 0 && totalValue > 0 ? round(((salePrice - totalValue) / totalValue) * 100, 1) : '';
  row.YEARS_SINCE_SALE = yearsSince(row.TRANS_DATE);

  // --- lead score: how interesting is this parcel to an investor or researcher ---
  const held = row.YEARS_SINCE_SALE === '' ? null : Number(row.YEARS_SINCE_SALE);
  let score = 0;
  if (row.OWNER_OCCUPIED === 'No') score += 30;
  if (row.OUT_OF_STATE_OWNER === 'Yes') score += 15;
  if (held !== null && held >= 15) score += 25;
  else if (held !== null && held >= 8) score += 10;
  if (row.IS_VACANT_LAND === 'Yes') score += 10;
  if (row.LAND_VALUE_PCT >= 70) score += 10;
  if (num(row.ACREAGE_ADJACENT_WITH_SAMEOWNER) > 0) score += 10;
  row.LEAD_SCORE = score > 100 ? 100 : score;

  if (row.LEAD_SCORE >= 65) row.LEAD_TIER = 'HOT';
  else if (row.LEAD_SCORE >= 35) row.LEAD_TIER = 'WARM';
  else row.LEAD_TIER = 'COLD';

  const flags = [];
  if (row.OWNER_OCCUPIED === 'No') flags.push('ABSENTEE_OWNER');
  if (row.OUT_OF_STATE_OWNER === 'Yes') flags.push('OUT_OF_STATE_OWNER');
  if (row.IS_VACANT_LAND === 'Yes') flags.push('VACANT_LAND');
  if (held !== null && held >= 15) flags.push('LONG_HELD');
  if (row.SALE_VS_MARKET_PCT !== '' && Number(row.SALE_VS_MARKET_PCT) <= -25) flags.push('SOLD_BELOW_MARKET');
  if (totalValue === 0) flags.push('NO_VALUATION');
  if (num(row.ACREAGE_ADJACENT_WITH_SAMEOWNER) > 0) flags.push('ADJACENT_PARCEL_SAME_OWNER');
  row.FLAGS = flags.join(', ');

  out.push({ json: row, pairedItem: { item: i } });
}

return out;

// One row per search, however many parcels came back.
function num(value) {
  const n = Number(String(value === null || value === undefined ? '' : value).replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? 0 : n;
}

function round(value, places) {
  const f = Math.pow(10, places);
  return Math.round(value * f) / f;
}

const groups = {};
const order = [];

for (const item of $input.all()) {
  const j = item.json;
  const key = String(j.SEARCH_ID || '');

  if (!groups[key]) {
    order.push(key);
    groups[key] = {
      SEARCH_ID: key,
      SEARCHED_TYPE: j.SEARCHED_TYPE || '',
      SEARCHED_WHAT: j.SEARCHED_WHAT || '',
      SEARCHED_LOCATION: j.SEARCHED_LOCATION || '',
      PROPERTIES_FOUND: 0,
      TOTAL_MARKET_VALUE: 0,
      TOTAL_ACREAGE: 0,
      ABSENTEE_COUNT: 0,
      OUT_OF_STATE_COUNT: 0,
      VACANT_LAND_COUNT: 0,
      BEST_LEAD_SCORE: -1,
      BEST_LEAD_TIER: 'COLD',
      TOP_OWNER: '',
      TOP_VALUE: -1,
    };
  }

  const g = groups[key];
  g.PROPERTIES_FOUND++;
  const value = num(j.MKT_VAL_TOT);
  g.TOTAL_MARKET_VALUE += value;
  g.TOTAL_ACREAGE += num(j.ACREAGE) || num(j.ACREAGE_CALC);
  if (j.OWNER_OCCUPIED === 'No') g.ABSENTEE_COUNT++;
  if (j.OUT_OF_STATE_OWNER === 'Yes') g.OUT_OF_STATE_COUNT++;
  if (j.IS_VACANT_LAND === 'Yes') g.VACANT_LAND_COUNT++;

  if (num(j.LEAD_SCORE) > g.BEST_LEAD_SCORE) {
    g.BEST_LEAD_SCORE = num(j.LEAD_SCORE);
    g.BEST_LEAD_TIER = j.LEAD_TIER || 'COLD';
  }
  if (value > g.TOP_VALUE) {
    g.TOP_VALUE = value;
    g.TOP_OWNER = j.OWNER || j.MAIL_NAME || '';
  }
}

const summaryDate = new Date().toISOString().slice(0, 10);

return order.map((key) => {
  const g = groups[key];
  return {
    json: {
      SEARCH_ID: g.SEARCH_ID,
      SEARCHED_TYPE: g.SEARCHED_TYPE,
      SEARCHED_WHAT: g.SEARCHED_WHAT,
      SEARCHED_LOCATION: g.SEARCHED_LOCATION,
      PROPERTIES_FOUND: g.PROPERTIES_FOUND,
      TOTAL_MARKET_VALUE: round(g.TOTAL_MARKET_VALUE, 2),
      AVG_MARKET_VALUE: g.PROPERTIES_FOUND > 0 ? round(g.TOTAL_MARKET_VALUE / g.PROPERTIES_FOUND, 2) : 0,
      TOTAL_ACREAGE: round(g.TOTAL_ACREAGE, 2),
      AVG_VALUE_PER_ACRE: g.TOTAL_ACREAGE > 0 ? round(g.TOTAL_MARKET_VALUE / g.TOTAL_ACREAGE, 2) : 0,
      ABSENTEE_COUNT: g.ABSENTEE_COUNT,
      OUT_OF_STATE_COUNT: g.OUT_OF_STATE_COUNT,
      VACANT_LAND_COUNT: g.VACANT_LAND_COUNT,
      BEST_LEAD_SCORE: g.BEST_LEAD_SCORE < 0 ? 0 : g.BEST_LEAD_SCORE,
      BEST_LEAD_TIER: g.BEST_LEAD_TIER,
      TOP_OWNER: g.TOP_OWNER,
      SUMMARY_DATE: summaryDate,
    },
  };
});
